function isOk(body, httpStatus) {
  if (!(httpStatus &gt;= 200 &amp;&amp; httpStatus &lt; 300)) return false;
  if (!body || typeof body !== &quot;object&quot; || Array.isArray(body)) return false;
  if (body.code == null) return false;
  for (let part = body; part; ) {
    if (part.code != null &amp;&amp; !(Number(part.code) &gt;= 200 &amp;&amp; Number(part.code) &lt; 300)) return false;
    const error = part.error;
    const empty = error == null ||
      (typeof error === &quot;object&quot; &amp;&amp; Object.keys(error).length === 0);
    if (!empty) return false;
    const next = part.data;
    part = next &amp;&amp; typeof next === &quot;object&quot; &amp;&amp; !Array.isArray(next) &amp;&amp;
      (&quot;code&quot; in next || &quot;error&quot; in next) ? next : null;
  }
  return true;
}

